insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-187', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'A current of 2.0 A is passed for 30 min through molten Al$_2$O$_3$ (Al = 27). The mass of aluminium liberated is', '["$0.336\\ \\mathrm{g}$","$1.008\\ \\mathrm{g}$","$0.112\\ \\mathrm{g}$","$9.00\\ \\mathrm{g}$"]'::jsonb, 0, '$Q = 2.0 \times 1800 = 3600\ \mathrm{C}$. $m = (27 \times 3600)/(3 \times 96500) \approx 0.336\ \mathrm{g}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'electrolysis-faraday') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
